from ingest_records import Reading, parse_readings, validate_current


def summarize(raw, adjust=None):
    readings = parse_readings(raw)
    total = 0
    for reading in readings:
        if reading is None:
            continue
        if not isinstance(reading, Reading):
            continue
        total += reading.amount

    if adjust is not None:
        adjust(readings)

    validate_current(readings)
    return {"before": total, "after": sum(reading.amount for reading in readings)}

