from dataclasses import dataclass


@dataclass
class Reading:
    amount: int


def parse_readings(raw):
    if type(raw) is not list:
        raise ValueError("list required")
    readings = []
    for amount in raw:
        if type(amount) is not int or amount < 0:
            raise ValueError("nonnegative integer required")
        readings.append(Reading(amount))
    return readings


def validate_current(readings):
    for reading in readings:
        if type(reading) is not Reading:
            raise ValueError("invalid adjusted reading")
        if type(reading.amount) is not int or reading.amount < 0:
            raise ValueError("invalid adjusted amount")

