import json


def read_optional_cache(open_cache, path):
    try:
        stream = open_cache(path)
    except FileNotFoundError:
        return None
    try:
        try:
            payload = json.loads(stream.read())
        except json.JSONDecodeError:
            return None
        return payload
    finally:
        stream.close()

